import { localStore, queryParams, sessionStore } from '@splendidlabz/utils/dom'

import { getNestedProperty } from '@splendidlabz/utils'

export function getValueFromSource({ source, list }) {
  return getNestedProperty(source, list)
}

export function getValueFromBrowserStorage(list) {
  const [storageKey, ...rest] = list
  const storageValue =
    localStore.get(storageKey) ||
    sessionStore.get(storageKey) ||
    queryParams.get(storageKey)

  return getNestedProperty(storageValue, rest)
}
